        raise ValueError("too many drops")
    if len(set(drops)) != len(drops):
        raise ValueError("duplicate drops")

    if not drops:
        return shortest_path(adj, origin, destination)

    best: Optional[Tuple[int, List[str]]] = None
    for perm in permutations(drops):
        points = [origin] + list(perm) + [destination]
        total_km = 0
        path: List[str] = []
        valid = True
        for i in range(len(points) - 1):
            sp = shortest_path(adj, points[i], points[i + 1])
            if sp is None:
                valid = False
